	/** 
	 * jumpstart the process by instantiating2 Publisher
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		publisherId = PublisherService.getPublisherInstance()
		.createPublisher( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PublisherService.getPublisherInstance()
				.createPublisher( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.publisherSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Publisher : " + successValue.getPublisherId());
							  if (successValue.getPublisherId().equals(publisherId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPublisherList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Publisher test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on publisher consumed")
					);
			subscriber.publisherSubscribe( publisherId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Publisher : " + successValue.getPublisherId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPublisherList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on publisher for publisherId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Publisher. 
	 */
	protected Publisher read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Publisher" );

		Publisher entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Publisher with primary key" );
		msg.append( publisherId );
		
		PublisherFetchOneSummary fetchOneSummary = new PublisherFetchOneSummary( publisherId );

		try {
			entity = PublisherService.getPublisherInstance().getPublisher( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Publisher " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Publisher.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Publisher." );

		StringBuilder msg = new StringBuilder( "Failed to update a Publisher : " );        
		Publisher entity = read();
		UpdatePublisherCommand command = generateUpdateCommand();
		command.setPublisherId(entity.getPublisherId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Publisher." );

			// for use later on...
			publisherId = entity.getPublisherId();

			PublisherService proxy = PublisherService.getPublisherInstance();  

			proxy.updatePublisher( command ).get();

			LOGGER.info( "-- Successfully saved Publisher - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + publisherId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Publisher.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Publisher." );

		Publisher entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Publisher with id " + publisherId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Publisher with id " + publisherId );

			throw e;
		}

		try{
			PublisherService.getPublisherInstance().delete( new DeletePublisherCommand( entity.getPublisherId() ) ).get();
			LOGGER.info( "-- Successfully deleted Publisher with id " + publisherId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Publisher with id " + publisherId );

			throw e;
		}
	}

	/**
	 * get all Publishers.
	 */
	protected List<Publisher> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Publishers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Publisher : " );        
		List<Publisher> collection  = new ArrayList<>();

		try {
			// call the static get method on the PublisherService
			collection = PublisherService.getPublisherInstance().getAllPublisher();
			assertNotNull( collection, "An Empty collection of Publisher was incorrectly returned.");
			
			// Now print out the values
			Publisher entity = null;            
			Iterator<Publisher> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPublisherId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

